// services/api.ts - дополненный
export interface Detection {
  type: string;
  bbox: [number, number, number, number];
  confidence?: number;
}

export interface FileInfo {
  id?: string;
  name: string;
  url: string;
  size?: number;
  object_name?: string;
  detections?: Detection[];
}

export interface UploadResponse {
  id: string;
  name: string;
  url: string;
  detections: Detection[];
  redactions: any[];
  object_name?: string;
}

export interface CensorshipRequest {
  pixel_size?: number;
  blur_strength?: number;
  method?: 'pixelate' | 'blur' | 'black_bar';
}

export interface CensorshipResponse {
  success: boolean;
  message: string;
  original_filename: string;
  processed_filename: string;
  object_name: string;
  url: string;
  censorship_method: string;
  pixel_size?: number;
  blur_strength?: number;
}

export interface CensorshipMethod {
  id: string;
  name: string;
  description: string;
  parameters: {
    name: string;
    type: string;
    min: number;
    max: number;
    default: number;
    description: string;
  }[];
}

export interface MinioInfo {
  username: string;
  minio_access_key?: string;
  files_bucket: string;
  user_folder: string;
  storage_used: string;
}

class ApiService {
  private baseUrl = 'http://localhost:8001';
  private token: string | null = null;

  setToken(token: string) {
    this.token = token;
  }

  private getHeaders(): HeadersInit {
    const headers: HeadersInit = {
      'Content-Type': 'application/json',
    };
    
    if (this.token) {
      headers['Authorization'] = `Bearer ${this.token}`;
    }
    
    return headers;
  }

  // Существующие методы...
  async uploadFiles(files: FileList): Promise<UploadResponse[]> {
    const formData = new FormData();
    Array.from(files).forEach(file => {
      formData.append('files', file);
    });

    const headers: HeadersInit = {};
    if (this.token) {
      headers['Authorization'] = `Bearer ${this.token}`;
    }
    // Не устанавливаем Content-Type для FormData - браузер установит автоматически с boundary

    const response = await fetch(`${this.baseUrl}/upload-multiple`, {
      method: 'POST',
      headers: headers,
      body: formData,
    });

    if (!response.ok) {
      throw new Error(`Upload failed: ${response.statusText}`);
    }

    return await response.json();
  }

  async getUserFiles(): Promise<FileInfo[]> {
    const response = await fetch(`${this.baseUrl}/files`, {
      headers: this.getHeaders(),
    });

    if (!response.ok) {
      throw new Error(`Failed to fetch user files: ${response.statusText}`);
    }

    return await response.json();
  }

  async deleteFile(objectName: string): Promise<void> {
    const response = await fetch(`${this.baseUrl}/files/${objectName}`, {
      method: 'DELETE',
      headers: this.getHeaders(),
    });

    if (!response.ok) {
      throw new Error(`Delete failed: ${response.statusText}`);
    }
  }

  async minioHealthCheck(): Promise<boolean> {
    try {
      const response = await fetch(`${this.baseUrl}/health`);
      if (response.ok) {
        const data = await response.json();
        return data.minio_connected === true;
      }
      return false;
    } catch {
      return false;
    }
  }

  // Новые методы для цензурирования
  async getCensorshipMethods(): Promise<CensorshipMethod[]> {
    const response = await fetch(`${this.baseUrl}/censor/methods`, {
      headers: this.getHeaders(),
    });

    if (!response.ok) {
      throw new Error(`Failed to fetch censorship methods: ${response.statusText}`);
    }

    const data = await response.json();
    return data.methods;
  }

  async censorImage(
    file: File, 
    method: string = 'pixelate', 
    parameters: Record<string, any> = {}
  ): Promise<CensorshipResponse> {
    const formData = new FormData();
    formData.append('file', file);

    // Строим URL с query параметрами (FastAPI Query параметры)
    const queryParams = new URLSearchParams();
    Object.entries(parameters).forEach(([key, value]) => {
      if (value !== undefined && value !== null) {
        queryParams.append(key, value.toString());
      }
    });
    
    const url = `${this.baseUrl}/censor/${method}${queryParams.toString() ? '?' + queryParams.toString() : ''}`;

    const headers: HeadersInit = {};
    if (this.token) {
      headers['Authorization'] = `Bearer ${this.token}`;
    }
    // Не устанавливаем Content-Type для FormData - браузер установит автоматически с boundary

    const response = await fetch(url, {
      method: 'POST',
      headers: headers,
      body: formData,
    });

    if (!response.ok) {
      const errorText = await response.text();
      throw new Error(`Censorship failed: ${response.statusText} - ${errorText}`);
    }

    return await response.json();
  }

  async getUserMinioInfo(): Promise<MinioInfo> {
    const response = await fetch(`${this.baseUrl}/users/me/minio-info`, {
      headers: this.getHeaders(),
    });

    if (!response.ok) {
      throw new Error(`Failed to fetch MinIO info: ${response.statusText}`);
    }

    return await response.json();
  }

  async getSystemStatus(): Promise<any> {
    const response = await fetch(`${this.baseUrl}/debug/system-status`);
    
    if (!response.ok) {
      throw new Error(`Failed to fetch system status: ${response.statusText}`);
    }

    return await response.json();
  }

  async getSystemInfo(): Promise<any> {
    const response = await fetch(`${this.baseUrl}/info`);
    
    if (!response.ok) {
      throw new Error(`Failed to fetch system info: ${response.statusText}`);
    }

    return await response.json();
  }

  async downloadFile(url: string, filename: string): Promise<void> {
    const response = await fetch(url);
    const blob = await response.blob();
    const downloadUrl = window.URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = downloadUrl;
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    window.URL.revokeObjectURL(downloadUrl);
  }
}

export const apiService = new ApiService();
